/// <summary>
/// Bound CLI options for the auto-wrong census. <see cref="Command"/> is the subcommand
/// (<c>census</c> or <c>pairs</c>); the positional paths follow it.
/// </summary>
public sealed class AutoWrongCensusOptions
{
	public const string SectionName = "AutoWrongCensus";

	public string? Command { get; set; }

	public string? TracePath { get; set; }

	public string? CensusTsvPath { get; set; }
}
","i":"Writing options"}

{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Parses the census CLI's positional syntax:
/// <c>census &lt;trace.jsonl&gt;</c> and <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.
/// Anything else (no command, unknown command, wrong arity) yields an empty dictionary;
/// the runner prints the usage and exits 1.
/// </summary>
public static class CommandLineArgumentParser
{
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase) && args.Length == 2)
		{
			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase) && args.Length == 3)
		{
			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
		}

		return dict;
	}
}
","i":"Writing argument parser"}

