/// <summary>Usage text for the auto-wrong census CLI.</summary>
public static class AutoWrongCensusUsage
{
	public static void Print()
	{
		Console.WriteLine("LetUsCook.AutoWrongCensus — F-428 P12.13 auto-wrong census");
		Console.WriteLine();
		Console.WriteLine("Usage:");
		Console.WriteLine("  census <trace.jsonl>");
		Console.WriteLine("      Classifies every auto-wrong line (auto == true && correct == false) of a");
		Console.WriteLine("      debug or batch HoldoutGate trace by relation (accepted row vs key row) and");
		Console.WriteLine("      site (reuse, override, curated, ranker). TSV on stdout, summary on stderr.");
		Console.WriteLine();
		Console.WriteLine("  pairs <census.tsv> <trace.jsonl>");
		Console.WriteLine("      For each census row with blocker=window and route compound|other, emits the");
		Console.WriteLine("      parsedName head and the key head words. TSV on stdout.");
		Console.WriteLine();
		Console.WriteLine("Exits 1 on a missing file, a refused trace set (D-029), or a bad invocation.");
	}
}
