{"content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// The census verdict for one auto-wrong line: exactly one <see cref="Relation"/> and one
/// <see cref="Site"/>, plus the audit fields the TSV columns carry.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout row id.</summary>
	public required string HoldoutId { get; init; }

	/// <summary>Line index within the recipe.</summary>
	public required int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public required string Set { get; init; }

	/// <summary>Accepted-row vs key-row relation (brief §4, first match wins).</summary>
	public required string Relation { get; init; }

	/// <summary>Decision site: <c>reuse</c>, <c>override</c>, <c>curated</c>, or <c>ranker</c>.</summary>
	public required string Site { get; init; }

	/// <summary>For <c>override</c> sites: <c>yes</c>/<c>no</c> — is the normalised rawText a key of <c>exact-overrides.json</c>; empty otherwise.</summary>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Accepted row's dataset tier (empty when the trace lacks it).</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key row's dataset tier (empty when the trace lacks it).</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row's combined <c>FoodState</c> mask (state | satisfiers), as the enum's flag string.</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row's combined <c>FoodState</c> mask (state | satisfiers), as the enum's flag string.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key description's head phrase (head term plus non-state leading words), space-joined.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Accepted row description, verbatim.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Key row description, verbatim.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line, verbatim.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Trace field a relation step needed but the line lacked (drives the <c>other</c> class); empty when none.</summary>
	public string MissingField { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c>: key-side qualifier words the accepted row lacks, space-joined.</summary>
	public string KeyOnlyQualifiers { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c>: accepted-side qualifier words the key row lacks, space-joined.</summary>
	public string AcceptedOnlyQualifiers { get; init; } = string.Empty;

	/// <summary>For <c>row-choice-tier</c>: which tier is higher, <c>key</c> or <c>accepted</c>.</summary>
	public string HigherTier { get; init; } = string.Empty;
}
