{"content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Resolver;
using LetUsCook.Fdc.Parsing;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate trace JSONL, classifies every auto-wrong line
/// (<c>auto == true &amp;&amp; correct == false</c>) with <see cref="AutoWrongClassifier"/>, and writes
/// the TSV to <c>Output</c> and the relation × site summary to <c>Error</c>. Refuses any trace whose
/// record <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusOptionsProvider options,
	AutoWrongClassifier classifier,
	System.IO.TextWriter output,
	System.IO.TextWriter error) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey", "acceptedTier",
		"keyTier", "acceptedState", "keyState", "parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = options.Value;

		if (string.IsNullOrEmpty(options.Command))
		{
			error.WriteLine("usage: AutoWrongCensus census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(options.TracePath))
		{
			error.WriteLine($"trace file not found: {options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch traces are read (D-029)");
			return 1;
		}

		return options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: await RunPairsAsync(options, lines, cancellationToken).ConfigureAwait(false);
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await foreach (var line in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				error.WriteLine($"refused: {path} is not a HoldoutGate trace JSONL: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "<none>"}' on {line.HoldoutId}#{line.LineIndex}");
			}

			results.Add(result);
		}

		output.WriteLine(string.Join('\t', TsvColumns));
		foreach (var r in results)
		{
			output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex.ToString(CultureInfo.InvariantCulture), Sanitize(r.Set),
				Sanitize(r.Relation), Sanitize(r.Site), Sanitize(r.OverrideKey), Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState), Sanitize(r.ParsedName),
				Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteSummary(results, unknownSite);
		return unknownSite > 0 ? 1 : 0;
	}

	private async Task<int> RunPairsAsync(AutoWrongCensusOptions options, IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(options.CensusTsvPath))
		{
			error.WriteLine($"census tsv not found: {options.CensusTsvPath}");
			return 1;
		}

		var rows = await ReadCensusRowsAsync(options.CensusTsvPath, cancellationToken).ConfigureAwait(false);
		if (rows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var missing = 0;
		foreach (var row in rows)
		{
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missing++;
				error.WriteLine($"no trace line for census row {row.HoldoutId}#{row.LineIndex}");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', classifier.KeyHeadPhrase(classifier.NormalizeTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.NormalizeTokens(First(line.ExpectedDescriptions))));
			output.WriteLine(string.Join('\t', Sanitize(row.HoldoutId), row.LineIndex.ToString(CultureInfo.InvariantCulture), Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			emitted++;
		}

		error.WriteLine($"pairs: emitted={emitted} missing={missing}");
		return missing > 0 ? 1 : 0;
	}

	private async Task<IReadOnlyList<(string HoldoutId, int LineIndex)>?> ReadCensusRowsAsync(string path, CancellationToken cancellationToken)
	{
		var header = (await File.ReadLinesAsync(path, cancellationToken).FirstAsync().ConfigureAwait(false)).Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf.TryAdd(header[i], i);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				error.WriteLine($"refused: {path} has no '{required}' column");
				return null;
			}
		}

		var rows = new List<(string, int)>();
		await foreach (var line in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			var blocker = cells[indexOf["blocker"]];
			var route = cells[indexOf["route"]];
			if (blocker.Equals("window", StringComparison.Ordinal)
				&& (route.Equals("compound", StringComparison.Ordinal) || route.Equals("other", StringComparison.Ordinal)))
			{
				rows.Add((cells[indexOf["holdoutId"]], int.Parse(cells[indexOf["lineIndex"]], CultureInfo.InvariantCulture)));
			}
		}

		return rows;
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int unknownSite)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} lines={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.OrderBy(g => g.Key.Relation, StringComparer.Ordinal)
			.ThenBy(g => g.Key.Site, StringComparer.Ordinal);
		error.WriteLine("relation\tsite\tcount");
		foreach (var group in matrix)
		{
			error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherRate = results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0;
		error.WriteLine($"relation other: {otherCount}/{results.Count} ({otherRate:0.0}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key, StringComparer.Ordinal);
		if (missing.Any())
		{
			foreach (var group in missing)
			{
				error.WriteLine($"missing field {group.Key}: {group.Count()}");
			}
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			error.WriteLine($"overrideKey hits: {overrideLines.Count(r => r.OverrideKey == "yes")}/{overrideLines.Count}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			// The resolver's own exact-phrase rule (P6.6) applied to the line's parsed name vs the
			// master slug it linked: false means the reuse came through the fdcId→master link, not
			// through a name match — the shape P12.7 labelled "mapping-reuse".
			var nameMatches = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
				if (atom is { LinkedIngredientId.Length: > 0 } &&
					IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					nameMatches++;
				}
			}

			error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is true: {nameMatches}/{reuseLines.Count}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			error.WriteLine($"row-choice-tier: key tier higher={keyHigher} accepted tier higher={tierLines.Count - keyHigher}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}

		if (unknownSite > 0)
		{
			error.WriteLine($"unknown site: {unknownSite}");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult result) =>
		_lastLine is { } line && line.HoldoutId == result.HoldoutId && line.LineIndex == result.LineIndex ? line : null;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
