{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace. TSV goes to the
/// output writer, the relation × site summary and every diagnostic to the error writer; the exit
/// code is the CLI contract (0 success, 1 missing input / refused set / unknown atom path).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	ExactOverrideKeyIndex overrideKeys,
	FdcNormalizer normalizer,
	TextWriter output,
	TextWriter error) : IAutoWrongCensusRunner
{
	private static readonly string[] AllowedSets = ["debug", "batch"];

	private static readonly string[] TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
		"acceptedTier", "keyTier", "acceptedState", "keyState",
		"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	private static readonly string[] PairsColumns = ["holdoutId", "lineIndex", "parsedNameHead", "keyHead", "rawText"];

	private static readonly Dictionary<string, int> TierRank = new(StringComparer.OrdinalIgnoreCase)
	{
		["Foundation"] = 4,
		["SrLegacy"] = 3,
		["Survey"] = 2,
		["Branded"] = 1,
	};

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			error.WriteLine($"trace file not found: {_options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set, StringComparer.OrdinalIgnoreCase));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch are read (D-029)");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(lines);
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, jsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				error.WriteLine($"refused: trace line is not valid JSON: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSites = 0;

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSites++;
				error.WriteLine($"unknown atom path on {line.HoldoutId}#{line.LineIndex}: '{AtomPath(line)}'");
			}

			results.Add(result);
		}

		output.WriteLine(string.Join('\t', TsvColumns));
		foreach (var r in results)
		{
			output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex, Sanitize(r.Set), Sanitize(r.Relation), Sanitize(r.Site), Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState),
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteSummary(results, unknownSites);
		return unknownSites > 0 ? 1 : 0;
	}

	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			error.WriteLine($"census tsv not found: {_options.CensusTsvPath}");
			return 1;
		}

		var wanted = ReadWindowRows(_options.CensusTsvPath);
		if (wanted is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		output.WriteLine(string.Join('\t', PairsColumns));

		var matched = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				error.WriteLine($"no trace line for census row {holdoutId}#{lineIndex}");
				continue;
			}

			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(FirstAtomParsedName(line))));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			output.WriteLine(string.Join('\t', Sanitize(holdoutId), lineIndex, Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			matched++;
		}

		error.WriteLine($"pairs: {matched}/{wanted.Count} window compound/other rows matched a trace line");
		return 0;
	}

	private HashSet<(string HoldoutId, int LineIndex)>? ReadWindowRows(string path)
	{
		var header = File.ReadLines(path).FirstOrDefault()?.Split('\t');
		if (header is null)
		{
			error.WriteLine($"census tsv is empty: {path}");
			return null;
		}

		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf.TryAdd(header[i], i);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				error.WriteLine($"census tsv is missing column '{required}'");
				return null;
			}
		}

		var wanted = new HashSet<(string, int)>();
		foreach (var raw in File.ReadLines(path).Skip(1))
		{
			var cells = raw.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (cells[indexOf["blocker"]] == "window"
				&& (cells[indexOf["route"]] == "compound" || cells[indexOf["route"]] == "other")
				&& int.TryParse(cells[indexOf["lineIndex"]], out var lineIndex))
			{
				wanted.Add((cells[indexOf["holdoutId"]], lineIndex));
			}
		}

		return wanted;
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int unknownSites)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} autoWrongLines={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (Relation: g.Key.Relation, Site: g.Key.Site, Count: g.Count()))
			.OrderBy(x => x.Relation, StringComparer.Ordinal)
			.ThenBy(x => x.Site, StringComparer.Ordinal);

		error.WriteLine("relation\tsite\tcount");
		foreach (var row in matrix)
		{
			error.WriteLine($"{row.Relation}\t{row.Site}\t{row.Count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField)
			.Select(g => $"{g.Key}={g.Count()}");
		error.WriteLine($"missingFields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = reuseLines.Count(r =>
		{
			var line = FindLine(r);
			var atom = line is null ? null : line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			if (atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId))
			{
				return false;
			}

			return !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId);
		});
		error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {reuseNameMismatch}/{reuseLines.Count}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank.GetValueOrDefault(r.KeyTier) > TierRank.GetValueOrDefault(r.AcceptedTier));
		error.WriteLine($"row-choice-tier: keyHigher={keyHigher} acceptedHigher={tierLines.Count - keyHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			error.WriteLine($"qualifier-diff {r.HoldoutId}#{r.LineIndex}: keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}

		if (unknownSites > 0)
		{
			error.WriteLine($"unknownSites={unknownSites}");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r)
	{
		// The summary re-derives the ShouldReuse statistic from the classified line; the runner keeps
		// the classified lines in order, so the Nth result maps to the Nth auto-wrong line.
		return _lastLine;
	}

	private static string AtomPath(TraceLine line) =>
		line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static string FirstAtomParsedName(TraceLine line) =>
		line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty;

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
