{"content":"using System.Text.Json;
using System.Text.Json.Serialization;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Executes the invocation.</summary>
	/// <param name="cancellationToken">Shutdown token.</param>
	/// <returns>Process exit code: 0 success, 1 any refusal or missing input.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>The two text sinks the runner writes to: TSV to stdout, summary/diagnostics to stderr.</summary>
/// <param name="Output">TSV sink.</param>
/// <param name="Error">Summary and error sink.</param>
public sealed record OutputWriters(TextWriter Output, TextWriter Error);

/// <summary>Default runner: classifies every <c>auto &amp;&amp; !correct</c> line of one trace.</summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly OutputWriters _writers;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation classifier.</param>
	/// <param name="normalizer">The production normalizer (for the <c>pairs</c> head folding).</param>
	/// <param name="writers">Output and error sinks.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_writers = writers;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = _options.Value;
		switch (options.Command.ToLowerInvariant())
		{
			case CommandLineArgumentParser.CensusCommand:
				return await RunCensusAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
			case CommandLineArgumentParser.PairsCommand:
				return await RunPairsAsync(options.CensusTsvPath, options.TracePath, cancellationToken).ConfigureAwait(false);
			default:
				await _writers.Error.WriteLineAsync("usage: AutoWrongCensus census <trace.jsonl> | AutoWrongCensus pairs <census.tsv> <trace.jsonl>").ConfigureAwait(false);
				return 1;
		}
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		var (records, refusal) = await LoadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (records is null)
		{
			await _writers.Error.WriteLineAsync(refusal).ConfigureAwait(false);
			return 1;
		}

		var autoWrong = new List<ClassificationResult>();
		foreach (var record in records)
		{
			if (record.Auto && !record.Correct)
			{
				var classified = _classifier.Classify(record);
				if (classified.Site.Length == 0)
				{
					await _writers.Error.WriteLineAsync(
						$"refused: line {record.HoldoutId}#{record.LineIndex} has an atom path that is not ranker|override|curated.").ConfigureAwait(false);
					return 1;
				}

				autoWrong.Add(classified);
			}
		}

		foreach (var row in autoWrong)
		{
			await _writers.Output.WriteLineAsync(TsvLine(
				row.HoldoutId, row.LineIndex, row.Set, row.Relation, row.Site, row.OverrideKey,
				row.AcceptedTier, row.KeyTier, row.AcceptedState, row.KeyState,
				row.ParsedName, row.KeyHead, row.AcceptedDesc, row.KeyDesc, row.RawText)).ConfigureAwait(false);
		}

		await WriteSummaryAsync(records.Count, autoWrong, cancellationToken).ConfigureAwait(false);
		return 0;
	}

	private async Task WriteSummaryAsync(int traceLines, IReadOnlyList<ClassificationResult> autoWrong, CancellationToken cancellationToken)
	{
		await _writers.Error.WriteLineAsync($"autoWrongCensus traced={traceLines} autoWrong={autoWrong.Count}").ConfigureAwait(false);

		await _writers.Error.WriteLineAsync("relation\tsite\tcount").ConfigureAwait(false);
		foreach (var byRelation in autoWrong.GroupBy(r => r.Relation, StringComparer.Ordinal).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			foreach (var cell in byRelation.GroupBy(r => r.Site, StringComparer.Ordinal).OrderBy(g => g.Key, StringComparer.Ordinal))
			{
				await _writers.Error.WriteLineAsync($"{byRelation.Key}\t{cell.Key}\t{cell.Count()}").ConfigureAwait(false);
			}
		}

		var otherCount = autoWrong.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherPercent = autoWrong.Count > 0 ? otherCount * 100.0 / autoWrong.Count : 0.0;
		await _writers.Error.WriteLineAsync($"other={otherCount}/{autoWrong.Count} ({otherPercent:F1}%)").ConfigureAwait(false);

		foreach (var missing in autoWrong.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			await _writers.Error.WriteLineAsync($"missingField {missing.Key}={missing.Count()}").ConfigureAwait(false);
		}

		var overrideLines = autoWrong.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		await _writers.Error.WriteLineAsync(
			$"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}").ConfigureAwait(false);

		var reuseLines = autoWrong.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var shouldReuseFalse = reuseLines.Count(r =>
			r.LinkedIngredientId.Length > 0
			&& !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), r.LinkedIngredientId));
		await _writers.Error.WriteLineAsync($"reuse lines with ShouldReuse(parsedName, linkedIngredientId)=false: {shouldReuseFalse}/{reuseLines.Count}").ConfigureAwait(false);

		var tierRows = autoWrong.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier);
		var keyHigher = tierRows.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierRows.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		await _writers.Error.WriteLineAsync($"row-choice-tier: key higher={keyHigher} accepted higher={acceptedHigher}").ConfigureAwait(false);

		foreach (var row in autoWrong.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			await _writers.Error.WriteLineAsync(
				$"qualifiers {row.HoldoutId}#{row.LineIndex} keyOnly=[{string.Join(' ', row.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', row.AcceptedOnlyQualifiers ?? [])}]").ConfigureAwait(false);
		}
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' not found.").ConfigureAwait(false);
			return 1;
		}

		var (records, refusal) = await LoadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (records is null)
		{
			await _writers.Error.WriteLineAsync(refusal).ConfigureAwait(false);
			return 1;
		}

		var traceByKey = records.ToDictionary(r => (r.HoldoutId, r.LineIndex));

		var censusLines = await File.ReadAllLinesAsync(censusTsvPath, cancellationToken).ConfigureAwait(false);
		if (censusLines.Length == 0)
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' is empty.").ConfigureAwait(false);
			return 1;
		}

		var header = censusLines[0].Split('\t');
		var idIndex = Array.IndexOf(header, "holdoutId");
		var lineIndexColumn = Array.IndexOf(header, "lineIndex");
		var blockerIndex = Array.IndexOf(header, "blocker");
		var routeIndex = Array.IndexOf(header, "route");
		if (idIndex < 0 || lineIndexColumn < 0 || blockerIndex < 0 || routeIndex < 0)
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' lacks one of holdoutId/lineIndex/blocker/route.").ConfigureAwait(false);
			return 1;
		}

		await _writers.Output.WriteLineAsync("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText").ConfigureAwait(false);
		var matched = 0;
		var unmatched = 0;
		foreach (var censusLine in censusLines.Skip(1))
		{
			var cells = censusLine.Split('\t');
			if (cells.Length <= Math.Max(routeIndex, lineIndexColumn))
			{
				continue;
			}

			if (cells[blockerIndex] != "window" || (cells[routeIndex] != "compound" && cells[routeIndex] != "other"))
			{
				continue;
			}

			if (!int.TryParse(cells[lineIndexColumn], out var lineIndex)
				|| !traceByKey.TryGetValue((cells[idIndex], lineIndex), out var traceRecord))
			{
				unmatched++;
				continue;
			}

			await _writers.Output.WriteLineAsync(TsvLine(
				traceRecord.HoldoutId,
				traceRecord.LineIndex,
				FoldHead(traceRecord.Atoms.Count > 0 ? traceRecord.Atoms[0].ParsedName : string.Empty),
				FoldKeyHead(traceRecord),
				traceRecord.RawText)).ConfigureAwait(false);
			matched++;
		}

		await _writers.Error.WriteLineAsync($"pairs emitted={matched} unmatchedCensusRows={unmatched}").ConfigureAwait(false);
		return 0;
	}

	private async Task<(IReadOnlyList<TraceLine>? Records, string Refusal)> LoadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			return (null, $"refused: trace '{tracePath}' not found.");
		}

		var records = new List<TraceLine>();
		var lineNumber = 0;
		foreach (var line in await File.ReadAllLinesAsync(tracePath, cancellationToken).ConfigureAwait(false))
		{
			lineNumber++;
			if (line.Length == 0)
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
				?? throw new InvalidOperationException($"trace line {lineNumber} deserialized to null");
			if (record.Set != "debug" && record.Set != "batch")
			{
				return (null, $"refused: set '{record.Set}' (D-029 allows debug|batch only) at line {lineNumber}.");
			}

			records.Add(record);
		}

		return (records, string.Empty);
	}

	private string FoldHead(string parsedName) =>
		string.Join(' ', _normalizer.NormalizeToTokens(parsedName).Select(IngredientLineResolver.SingularizeToken));

	private string FoldKeyHead(TraceLine record) =>
		record.ExpectedDescriptions.Count == 0
			? string.Empty
			: string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(record.ExpectedDescriptions[0])));

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string TsvLine(params object[] cells) =>
		string.Join('\t', cells.Select(c => Sanitize(c?.ToString() ?? string.Empty)));

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
